typedef float nlVector3d[3];

extern float sqrtf(float);
extern float nlDotProduct3d(nlVector3d, nlVector3d);
extern void nlAddVect3d(nlVector3d &, const nlVector3d &, const nlVector3d &);
extern void nlSubVect3d(nlVector3d &, const nlVector3d &, const nlVector3d &);
extern void nlScaleVect3d(nlVector3d &, const nlVector3d &, float);

float nlDistancePointSegment( const nlVector3d & p,
                              const nlVector3d & n1, const nlVector3d & n2,
                              nlVector3d & hit_point )
{
  nlVector3d n;
  nlSubVect3d( n, n2, n1 );

  float n_len = nlDotProduct3d(n, n);
  if (n_len > 0.0f)
    n_len = sqrtf(n_len);

  // cover the zero length segment case
  if (n_len > 0.0f)
  {
    nlScaleVect3d( n, n, 1.0f / n_len );
  }

  nlVector3d c1;
  nlSubVect3d( c1, p, n1 );

  float ofs = nlDotProduct3d( c1, n );
  if (ofs < 0.0f) 
    ofs = 0.0f;
  else if (ofs > n_len) 
    ofs = n_len;

  nlScaleVect3d( hit_point, n, ofs );
  nlAddVect3d( hit_point, n1, hit_point );

  nlVector3d temp_vec;
  nlSubVect3d( temp_vec, hit_point, p );
  float ret_val = nlDotProduct3d( temp_vec, temp_vec );
  if (ret_val > 0.0f)
    ret_val = sqrtf(ret_val);

  return ret_val;
}
